import os, json
HERE = os.path.dirname(os.path.abspath(__file__)); N = json.load(open(os.path.join(HERE, "numbers_inpt.json")))
def th(x, d=0): return f"{x:,.{d}f}"
def ci(k, src="main", lab=True):
    e, lo, hi = (N[src][k] if isinstance(src, str) else src)
    return f"{e:.3f} (95% CrI {lo:.3f}-{hi:.3f})" if lab else f"{e:.3f} ({lo:.3f}-{hi:.3f})"
def tc(k, src): return ci(k, src, False)
def pct(x): return f"{100 * x:.0f}%"
T1 = N["T1"]; HC = N["hc"]; PC = N["pc"]
TITLE = "Korean districts with more hospital beds and long-term care hospitals have more inpatient days per resident"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower()
KEYWORDS = "Hospitalization; Length of stay; Long-term care hospitals; Hospital bed capacity; Small-area analysis; Republic of Korea"
RUNNING = "Bed supply and inpatient days in Korea"

ABSTRACT = [
("Objectives", "To describe where Korean residents spend more days in hospital than their age and sex predict, and to examine whether district hospital bed and long-term care hospital supply, need indicators, and physical activity are associated with inpatient days."),
("Design", "Ecological panel study."),
("Setting and Participants", f"All residents of {N['n_districts']} districts in the Republic of Korea, 2011-2024 ({th(N['n_rows'])} district-years; {N['days_total_bn']:.2f} billion inpatient days)."),
("Methods", "Inpatient days in hospitals inside and outside each district of residence came from National Health Insurance statistics. Expected days were indirectly standardized for sex and 5-year age group. Bayesian spatio-temporal negative binomial models related standardized inpatient days to 9 district characteristics with 5 fixed adjustments, followed by 200 covariate subsets, space-time interaction models, 1- and 2-year lags, and between- and within-district decomposition."),
("Results", f"Inpatient days per resident rose from {PC['2011']:.2f} in 2011 to {PC['2019']:.2f} in 2019 and were {PC['2024']:.2f} in 2024. The district ratio of observed to expected days ranged from {N['sur_p10']:.2f} to {N['sur_p90']:.2f} (10th-90th percentile), with a stable ranking (Kendall W {N['kendall_w']:.2f}); hot spots lay in the southwest and around Busan. Per 1 SD, inpatient days were higher with more hospital beds (rate ratio {tc('beds_per_1000', 'main')}), long-term care hospitals ({tc('ltc_hospitals', 'main')}), and Medical Aid type 1 beneficiaries ({tc('medicaid1_share', 'main')}). These associations persisted with district-specific trends, lagged covariates, and between- and within-district contrasts; bed density was not positively associated with outpatient visit-days. A small association with moderate physical activity disappeared with district-specific trends."),
("Conclusions and Implications", "Residents of districts with more hospital beds and long-term care hospitals spent more days in hospital, a pattern consistent with supply-sensitive inpatient care, although reverse causation and unmeasured confounding cannot be excluded. Regional planning of long-term care hospital capacity and of alternatives to institutional stays may need to consider bed supply alongside need."),
]

INTRO = [
f"Korea has more hospital beds per person than any other member of the Organisation for Economic Co-operation and Development and one of the longest average hospital stays [@oecd2023health]. Under a single-payer insurance system with fee-for-service payment to mostly private providers, the number of beds grew rapidly, and long-term care hospitals became a major setting of care for older adults [@kwon2009thirty; @cho2023effects]. Many older patients in these hospitals stay for months, and long-term care hospitals are now a common setting at the end of life [@kim2026longterm]. The introduction of long-term care insurance in 2008 did not consistently shorten hospital stays [@hyun2014does; @kim2018implementation; @cho2023effects].",
f"Small-area studies have long shown that neighboring populations of similar age use very different amounts of hospital care [@wennberg1973small; @wennberg2002geography; @corallo2014systematic]. Need, such as morbidity and poverty, explains part of this variation [@andersen1995revisiting]. Supply explains another part. Roemer's observation that a built bed tends to be a filled bed has been examined repeatedly, with estimates ranging from no effect to a substantial increase in admissions for each added bed [@roemer1961bed; @ginsburg1983bed; @fisher2000associations; @delamater2013more; @shwartz2011bringing]. In Korea, districts with more beds have more hospitalizations for conditions that are usually managed in ambulatory care [@kim2019hospitalizations; @kim2019spatial], and Medical Aid beneficiaries, who pay almost nothing for care, use more inpatient days than insured people [@kong2020factors; @kim2026comparison; @han2026medical; @lee2020effect]. Physically active people are admitted to hospital less often, and districts with more active populations might therefore use fewer inpatient days [@sari2009physical; @tsuji2003impact; @min2016excess; @langsetmo2019association].",
"No study has mapped inpatient days of residents across all Korean districts over a long period, or asked whether such a map follows bed and long-term care hospital supply, need, or physical activity once age and sex are taken into account. This study used 14 years of national insurance statistics to describe where residents spend more days in hospital than expected and how stable that pattern is. It then examined the associations of district hospital bed and long-term care hospital supply, need indicators, and physical activity with standardized inpatient days, and tested whether these associations persist in models that allow district-specific trends and use lagged covariates.",
]

METHODS = [
("Study Design and Data",
 f"This ecological panel study covered {N['n_districts']} districts (si, gun, and gu) from 2011 to 2024. The outcome was the annual number of inpatient days of residents, defined by the National Health Insurance Service as the sum of inpatient days in hospitals located in the district of residence and in hospitals outside it, for all diagnoses and for both National Health Insurance and Medical Aid beneficiaries [@web:nhis2026regional]. It includes days in acute, psychiatric, and long-term care hospitals but not stays in long-term care insurance facilities (nursing homes), which are not hospital care. Districts were linked by administrative code; general districts within cities were aggregated, giving {th(N['n_rows'])} district-years. Sejong, which appears in the source table only at the province level, was retained as a district. In {N['zero_in_cells']} district-years in 5 districts without an inpatient facility, all inpatient days were spent outside the district; 7 of these cells were blank in the source and were set to 0. Resident populations by sex and 5-year age group came from resident registration statistics [@web:mois2026population]; the 2023 population of Changwon was corrected to the official figure (1,009,038). The institutional review board of the author's institution approved the study and waived informed consent because only published aggregate statistics were used (details on the title page). Reporting follows the STROBE and RECORD statements [@vonelm2007strengthening; @benchimol2015reporting].",
 f"Expected inpatient days were obtained by indirect standardization [@inskip1983methods]: national inpatient-day rates for each year in 2 sexes and 18 age groups (to 85 years or older) were applied to each district's population and rescaled so that national expected and observed totals matched. The ratio of observed to expected days is the standardized inpatient-day ratio. Standardization reduced the Spearman correlation between district rates and the share of residents aged 80 years or older from {N['rho80_crude']:.2f} to {N['rho80_std']:.2f}. The national table summed to 82% to 85% of the district totals in every year, probably because the 2 tables count insured populations and days differently; this stable difference is absorbed by the annual rescaling, and a sensitivity analysis used expected days without age and sex standardization."),
("District Characteristics",
 "Nine characteristics were examined in 3 groups (Appendix Table 1). Physical activity was represented by the age-standardized walking and moderate-or-higher physical activity rates from the Community Health Survey [@kang2015korea] and by public and village sports facilities per 100,000 residents. Need was represented by the basic livelihood security (public assistance) recipient rate, Medical Aid type 1 beneficiaries treated per 100 residents (a utilization-based count, so its users also contribute to the outcome), and chewing discomfort among adults aged 65 years or older, a marker of oral frailty. Supply was represented by hospital beds per 1,000 residents and long-term care hospitals per 100,000 residents aged 65 years or older. Five adjustments used in all analyses of this design were included in every model: the urban population share, physicians per 1,000 residents, the sex ratio, fiscal autonomy, and the share aged 80 years or older. Cardiopulmonary resuscitation awareness, the road paving rate, and fires per 10,000 residents served as negative-control exposures. Public assistance rates for 2021-2023 that were below one-fifth or above 5 times the 2020 and 2024 mean of the same district (10 cities with general districts) were set to missing and linearly interpolated within districts. Covariates were standardized to 1 SD."),
("Statistical Analysis",
 f"Inpatient days were modeled with a negative binomial likelihood, chosen over the Poisson by the widely applicable information criterion (WAIC) [@gelman2014understanding], with the log of expected days as the offset, a Besag-York-Mollié 2 district effect on a contact graph of 593 neighboring pairs [@besag1991bayesian; @riebler2016intuitive], and random-walk and independent year effects, with penalized-complexity priors [@simpson2017penalising]. Models were fitted by integrated nested Laplace approximation [@rue2009approximate] (R-INLA 25.10.19) in R version 4.6.0 [@web:rcore2026]. Rate ratios per 1 SD are reported with 95% credible intervals (CrIs); intervals were not adjusted for multiplicity, so about {N['chance_n']:.1f} of 9 intervals could exclude 1 by chance. Global Moran's I [@moran1950notes] and Getis-Ord Gi* hot and cold spots of the 14-year ratio [@ord1995local] described the map, and Kendall's W described the stability of district rankings.",
 "Robustness was assessed in 5 ways. First, 200 models used random subsets of the 9 characteristics, always with the 5 adjustments [@steegen2016increasing]; a characteristic was subset-stable when its interval excluded 1 in at least 75% of subsets containing it. Second, Knorr-Held space-time interaction types I-IV were added; types II and IV allow district-specific trends [@knorrheld2000bayesian]. Third, because supply may follow demand, covariates were lagged by 1 and 2 years, and subset-stable characteristics were split into district means and within-district deviations [@bell2015explaining]. Fourth, 45 alternative specifications varied the likelihood, time and province-by-year effects, a Spatial+ adjustment [@dupont2022spatial], and omitted provinces and years (Appendix Table 3); 3 further analyses used a queen contiguity graph, dropped the 80-and-over adjustment, and used unstandardized expected days. Fifth, the principal model was refitted with total and outpatient visit-days of residents, standardized for sex and age, as comparison outcomes; supply-sensitive inpatient care predicts associations of bed supply with inpatient days but not with outpatient visits. Hot spots, other districts, and cold spots were also compared descriptively on days per inpatient (inpatient days divided by the summed numbers of patients treated inside and outside the district) and on supply. Associations describe districts, not individuals [@morgenstern1995ecologic]."),
]

RESULTS = [
("A Stable Southern Excess",
 f"Residents spent {N['days_total_bn']:.2f} billion days in hospital over 2011-2024. Inpatient days per resident rose from {PC['2011']:.2f} in 2011 to {PC['2019']:.2f} in 2019, fell to {PC['2020']:.2f} in 2020, and were {PC['2024']:.2f} in 2024; about 58% to 60% of days each year were spent in hospitals outside the district of residence (Table 1; Figure 1B). The 14-year standardized ratio ranged from {N['sur_min']:.2f} to {N['sur_max']:.2f} (10th-90th percentile {N['sur_p10']:.2f}-{N['sur_p90']:.2f}). Moran's I was {N['moran_min']:.2f} to {N['moran_max']:.2f} each year, Kendall's W was {N['kendall_w']:.2f}, and the rank correlation between 2011 and 2024 was {N['rho_2011_2024']:.2f}. Gi* identified {N['gi_hot']} hot spots, in Jeonnam ({N['gi_hot_sido']['Jeonnam']}), Busan ({N['gi_hot_sido']['Busan']}), Gyeongnam ({N['gi_hot_sido']['Gyeongnam']}), Jeonbuk ({N['gi_hot_sido']['Jeonbuk']}), Gwangju ({N['gi_hot_sido']['Gwangju']}), and Ulsan ({N['gi_hot_sido']['Ulsan']}), and {N['gi_cold']} cold spots in Seoul ({N['gi_cold_sido']['Seoul']}), Gyeonggi ({N['gi_cold_sido']['Gyeonggi']}), and Gangwon ({N['gi_cold_sido']['Gangwon']}) (Figure 1A). Hot spots included {N['gi_hot_gun']} counties, {N['gi_hot_si']} cities, and {N['gi_hot_gu']} urban wards. Compared with cold spots, hot spots had a median of {HC['hot']['dpp']:.1f} vs {HC['cold']['dpp']:.1f} days per inpatient, {HC['hot']['beds']:.1f} vs {HC['cold']['beds']:.1f} beds per 1,000 residents, and {HC['hot']['ltc']:.1f} vs {HC['cold']['ltc']:.1f} long-term care hospitals per 100,000 residents aged 65 years or older, and a smaller share of days spent outside the district ({100*HC['hot']['out']:.0f}% vs {100*HC['cold']['out']:.0f}%) (Figure 1C)."),
("District Characteristics",
 f"Adding the 9 characteristics lowered the WAIC from {th(N['waic_forced'],1)} to {th(N['waic_main'],1)} (Table 2). Inpatient days were higher with more hospital beds ({ci('beds_per_1000')}), long-term care hospitals ({ci('ltc_hospitals')}), and Medical Aid type 1 beneficiaries ({ci('medicaid1_share')}), and slightly lower with more moderate-or-higher physical activity ({ci('moderate_pa_rate')}). Walking, sports facilities, the public assistance rate ({tc('basic_livelihood_rate', 'main')}), and chewing discomfort were not associated. Among the adjustments, physician density was associated with fewer days ({tc('physicians_per_1000', 'main')}). Of the negative-control exposures, fires were associated with more days ({tc('fires_per_10000', 'nc')}), cardiopulmonary resuscitation awareness had an interval reaching 1 ({tc('cpr_awareness_rate', 'nc')}), and road paving was not associated ({tc('road_pavement_rate', 'nc')}). The structured spatial effect accounted for {N['vp_spatial']}% of the variance of the linear predictor and the 9 characteristics for {N['vp_hyp']}%; residual Moran's I was {N['rm_spec']['principal']:.2f}."),
("Robustness",
 f"Beds, long-term care hospitals, and Medical Aid were credible in 100% of the subsets that contained them and moderate physical activity in {pct(N['mv']['moderate_pa_rate'][0])}; the public assistance rate was credible in {pct(N['mv']['basic_livelihood_rate'][0])} and, with district-specific trends, {tc('basic_livelihood_rate', 'KH_typeII')}. All 4 associations persisted with a type I interaction, which fitted best (WAIC {th(N['KH_typeI_waic'],1)}). With district-specific trends (types II and IV), the bed (type II {tc('beds_per_1000', 'KH_typeII')}; type IV {tc('beds_per_1000', 'KH_typeIV')}), long-term care hospital ({tc('ltc_hospitals', 'KH_typeII')}; {tc('ltc_hospitals', 'KH_typeIV')}), and Medical Aid ({tc('medicaid1_share', 'KH_typeII')}; {tc('medicaid1_share', 'KH_typeIV')}) associations were smaller but remained credible, whereas moderate physical activity was not ({tc('moderate_pa_rate', 'KH_typeII')}) (Figure 2). With 2-year lags, the rate ratios were {tc('beds_per_1000', 'E2_lag2')} for beds, {tc('ltc_hospitals', 'E2_lag2')} for long-term care hospitals, and {tc('medicaid1_share', 'E2_lag2')} for Medical Aid. Each was credible both between districts (beds {tc('beds_per_1000__between', 'bw')}; long-term care hospitals {tc('ltc_hospitals__between', 'bw')}; Medical Aid {tc('medicaid1_share__between', 'bw')}) and within districts over time ({tc('beds_per_1000__within', 'bw')}; {tc('ltc_hospitals__within', 'bw')}; {tc('medicaid1_share__within', 'bw')}); physical activity was credible only within districts. With 1-year lags, Spatial+ adjustment, and province-by-year effects, the bed ratios were {tc('beds_per_1000', 'E1_lag1')}, {tc('beds_per_1000', 'D1_spatial_plus')}, and {tc('beds_per_1000', 'C4_sido_year_iid')}. Beds and long-term care hospitals were credible in all 45 alternative specifications and Medical Aid in {N['ret']['medicaid1_share'][0]}. With unstandardized expected days, the Medical Aid ratio increased to {tc('medicaid1_share', 'sc')}. Bed associations were credible in all 3 calendar periods and in every region; the long-term care hospital association was absent in Yeongnam ({tc('ltc_hospitals_per_100k_65|Yeongnam', 'reg')}), and the Medical Aid association was absent in 2011-2015 and in the Honam region ({tc('ext__medicaid1_share|Honam', 'reg')}) (Appendix Tables 4-6). Without a district random effect, the Medical Aid association disappeared ({tc('medicaid1_share', 'no_spatial')}). Posterior predictive 95% intervals covered {N['ppc95']:.1f}% of district-years, and in a 2024 out-of-sample check, 95% predictive intervals covered {N['oos_cov']:.1f}% of districts (median absolute error {N['oos_mape']:.1f}%). E-values for the point estimates were {N['evalue']['beds_per_1000'][0]:.2f} for beds, {N['evalue']['ltc_hospitals'][0]:.2f} for long-term care hospitals, and {N['evalue']['medicaid1_share'][0]:.2f} for Medical Aid (Appendix Table 7)."),
("Comparison Outcomes",
 f"With outpatient visit-days as the outcome, bed density was slightly inversely associated, with a rate ratio of {tc('OUTV|beds_per_1000', 'nco')} and long-term care hospitals {tc('OUTV|ltc_hospitals', 'nco')}, whereas Medical Aid remained associated ({tc('OUTV|medicaid1_share', 'nco')}). With total visit-days, of which inpatient days are a small part, the bed association was {tc('HCUVC|beds_per_1000', 'nco')} (Figure 2; Appendix Table 7)."),
]

DISCUSSION = [
"Residents of a belt of southwestern districts and of Busan and its neighbors spent up to twice as many days in hospital as their age and sex predicted, and this ranking hardly changed over 14 years. Hot spots had longer stays per patient and more beds and long-term care hospitals. Across districts and within districts over time, bed and long-term care hospital supply were associated with more inpatient days, and these associations survived space-time interactions, lags, and alternative specifications. Bed density was not positively associated with outpatient visits. Medical Aid enrollment was associated with both inpatient and outpatient use.",
"### Supply and Inpatient Days",
"The bed association agrees with Roemer's law and with studies in which bed supply predicted admissions after accounting for need [@roemer1961bed; @ginsburg1983bed; @delamater2013more; @shwartz2011bringing]. In Korea, districts with more beds have more admissions for ambulatory care-sensitive conditions [@kim2019hospitalizations; @kim2019spatial]. The present findings extend these studies to total inpatient days of all residents and to long-term care hospitals. Hot spots also had more days per inpatient, which may partly reflect longer stays; this descriptive measure counts patients treated both inside and outside their district twice, which lowers it most where more care is used elsewhere, as in the cold spots. In long-term care hospitals, stays are long and many older adults remain until death [@kim2026longterm], and previous studies suggest that admissions and discharges reflect the availability of care at home as well as medical need; the 2008 long-term care insurance did not consistently shorten stays [@hyun2014does; @kim2018implementation; @cho2023effects]. That beds were associated with more inpatient days but not with more outpatient visits is what supply-sensitive inpatient care predicts [@fisher2003implicationsa; @wennberg2002geography]. The 2 directions cannot, however, be separated here. Hospitals may be built where demand is high; because supply changes slowly, lags of 1 and 2 years add little information about direction, and the within-district associations are also open to reverse causation. Physician density, a fixed adjustment, was associated with fewer inpatient days, which may reflect better access to outpatient care where physicians are concentrated. Because about 60% of inpatient days were spent outside the district of residence, residence-based supply measures only part of the beds that residents use; cold spots in the capital region relied most on hospitals elsewhere.",
"### Need, Medical Aid, and Physical Activity",
"Medical Aid type 1 beneficiaries have more chronic illness, disability, and psychiatric illness and pay almost nothing for care, and they are over-represented among long-stay psychiatric and long-term care hospital patients [@chung2010determinants; @kim2026longterm; @kong2020factors]. Medical Aid enrollment was associated with both inpatient and outpatient use, depended on the district random effect, became stronger after 2015, and was absent in Honam. In Japan, psychiatric admissions of public assistance recipients also vary geographically with bed supply [@okumura2019geographical]. These patterns may reflect a combination of need and low prices rather than a factor that explains the southern excess, and because the measure counts beneficiaries who used care, part of the association is compositional. The public assistance rate and chewing discomfort, other markers of need, were not associated once supply was in the model. The small association of moderate physical activity with fewer inpatient days was confined to within-district changes and disappeared when district-specific trends were allowed. Individual studies show that active people use fewer hospital days [@sari2009physical; @tsuji2003impact; @langsetmo2019association], but this analysis provides no robust support for an area-level association.",
"### Strengths and Limitations",
"The study included every resident and district for 14 years, standardized for sex and 5-year age group, and tested associations with space-time interaction models, lags, and comparison outcomes. It has limitations. First, it is ecological, and associations do not describe individuals [@morgenstern1995ecologic]. Second, inpatient days combine admissions and length of stay, include all diagnoses, and do not measure appropriateness of care; above-expected use is not inappropriate use. Third, the national rate table covered fewer days than the district tables, which may reflect differing coverage; unstandardized expected days gave the same conclusions for beds and long-term care hospitals but a larger Medical Aid association. Fourth, supply was measured where residents live, not where they are treated. Fifth, the fire negative control was associated with inpatient days with a rate ratio similar to that of long-term care hospitals, residual spatial autocorrelation remained in all specifications with a spatial effect (Moran's I about 0.24), and the E-values were modest, so unmeasured district characteristics, such as the supply of long-term care insurance facilities and home care or the mix of private and public hospitals, may confound the associations. Sixth, small rate ratios per 1 SD became credible because of the large number of district-years; their size matters more than their credibility.",
]
CONCLUSION = ["After standardization for sex and age, inpatient days per resident differ about 2-fold between the 10th and 90th percentile Korean districts, and the excess in Jeonnam, Gwangju, and Jeonbuk and in Busan and Gyeongnam has persisted for 14 years. Districts with more hospital beds and long-term care hospitals have more inpatient days, an association that persists across specifications and is not seen for outpatient visits. Regional planning of hospital and long-term care hospital capacity, together with community and home-based alternatives for older adults, should consider how existing supply relates to the days residents spend in hospital, while research using individual records examines how supply relates to admissions and length of stay."]
